```python
from collections import deque

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        x, y, w = map(int, lines[2 + i].split())
        edges.append({'u': x, 'v': y, 'w': w, 'id': i + 1})
        adj[x].append((y, i + 1))
        adj[y].append((x, i + 1))

    def is_disconnected(removed_ids):
        visited = [False] * (n + 1)
        visited[s] = True
        queue = deque([s])

        while queue:
            node = queue.popleft()
            if node == t:
                return False
            for neighbor, eid in adj[node]:
                if eid not in removed_ids and not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return True

    # Try 0 edges
    if not is_disconnected(set()):
        return "0\n0"

    # Check 1 edge removal
    best_result_1 = None
    for i in range(m):
        eid = edges[i]['id']
        if is_disconnected({eid}):
            cost = edges[i]['w']
            if best_result_1 is None or cost < best_result_1[0]:
                best_result_1 = (cost, 1, [eid])

    # Check 2 edge removal
    best_result_2 = None
    for i in range(m):
        for j in range(i + 1, m):
            eid1, eid2 = edges[i]['id'], edges[j]['id']
            if is_disconnected({eid1, eid2}):
                cost = edges[i]['w'] + edges[j]['w']
                if best_result_2 is None or cost < best_result_2[0]:
                    best_result_2 = (cost, 2, [eid1, eid2])

    if best_result_1:
        return f"{best_result_1[0]}\n{best_result_1[1]}\n{best_result_1[2][0]}"
    elif best_result_2:
        return f"{best_result_2[0]}\n{best_result_2[1]}\n{' '.join(map(str, best_result_2[2]))}"
    else:
        return "-1"
