import sys

def is_gp(seq):
    """
    Check if a sequence is a geometric progression.
    For three consecutive terms a, b, c to be in GP, we need b² = a × c.
    """
    n = len(seq)
    if n <= 2:
        return True

    # If all zeros, it's a GP (ratio can be anything, but all terms are 0)
    if all(x == 0 for x in seq):
        return True

    # For each triplet (a, b, c), check if b² = a * c
    for i in range(n - 2):
        a, b, c = seq[i], seq[i+1], seq[i+2]
        if b * b != a * c:
            return False

    return True

def solution(input_str):
    """
    Main solution function that parses input and returns the result.
    """
    # Parse input
    parts = input_str.strip().split()
    if len(parts) < 1:
        return "2\n"
    n = int(parts[0])
    if len(parts) < n + 1:
        # Handle malformed input
        seq = [int(x) for x in parts[1:]]
    else:
        seq = [int(x) for x in parts[1:n+1]]

    # Check if already a GP
    if is_gp(seq):
        return "0\n"

    # Try removing each element one by one
    for i in range(len(seq)):
        new_seq = seq[:i] + seq[i+1:]
        if is_gp(new_seq):
            return "1\n"

    # Cannot form a GP by removing one element
    return "2\n"

