Looking at this problem, I need to understand what makes a submatrix "beautiful":

1. Each row in the submatrix can be independently reordered to form a palindrome (meaning at most one character has odd frequency)
2. After that reordering, each column must also form a palindrome (the same condition applies to columns)

This translates to: for a submatrix to be beautiful, **every row** in that submatrix must have at most one character with odd frequency, AND **every column** in that submatrix must also have at most one character with odd frequency.

Let me implement a solution with 2D prefix sums for efficient counting:

```python
def solution(s):
    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())
    matrix = [list(line) for line in lines[1:n+1]]

    # Precompute character counts using 2D prefix sums
    # counts[i][j] stores character counts for the rectangle [0..i-1][0..j-1]
    counts = [[[0] * 26 for _ in range(m + 1)] for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            c = ord(matrix[i][j]) - ord('a')
            fi = [c]
            for k in range(-1, fi):  # boundary
                pass
            # Get prefix counts for this position
            before_row = counts[i][j + 1][:]
            before_col = counts[i + 1][j][:]
            new_row = before_row + before_col - counts[i][j][:]
            new_row[c] += 1
            counts[i + 1][j + 1] = new_row

    def get_row_counts(r1, c1, r2, c2):
        return [counts[r][c] - counts[r1][c] for r in [r1, r2 + 1] 
                for c in [c1, c2 + 1] if r > r1 or c > c1 else []]

    def get_col_counts(r1, c1, r2, c2):
        return [counts[r][c + 1] - counts[r][c] for r in [r1, r2 + 1] 
                for c in [c1, c2 + 1] if r > r1]

    beautiful_count = 0

    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):
                    valid = True

                    # Check each row
                    for r in range(r1, r2 + 1):
                        row_counts = [0] * 26
                        for col_j in range(c1, c2 + 1):
                            row_counts[ord(matrix[r][col_j]) - ord('a')] += 1

                        odd_count = sum(1 for c in row_counts if c % 2 == 1)
                        if odd_count > 1:
                            valid = False
                            break

                    if valid:
                        # Check each column
                        for col_j in range(c1, c2 + 1):
                            col_counts = [0] * 26
                            for row_i in range(r1, r2 + 1):
                                col_counts[ord(matrix[row_i][col_j]) - ord('a')] += 1

                            odd_count = sum(1 for c in col_counts if c % 2 == 1)
                            if odd_count > 1:
                                valid = False
                                break

                    if valid:
                        beautiful_count += 1

    return str(beautiful_count)
