    INF = 100000

    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.inf_edges = set()
        self.source = None
        self.sink = None

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])
        if cap == self.INF:
            self.inf_edges.add((u, v))

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, rev in self.graph[u]:
