    best = 0
    for i in range(n + 1):
        for j in range(m + 1):
            for st in range(k):
                if dp[i][j][st] > best:
                    best = dp[i][j][st]

    if best == 0:
        return "0"

    # Reconstruction
    res = []
    i, j = n, m

    while i > 0 and j > 0:
        if s1[i-1] == s2[j-1] and dp[i][j] == dp[i-1][j-1] + 1:
            res.append(s1[i-1])
            i -= 1
            j -= 1
        elif dp[i-1][j] >= dp[i][j-1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(res))
