Looking at this problem, I need to:
1. Replace `?` characters with W, L, or D
2. Ensure that at the end, `|wins - losses| = k`
3. Ensure that at no intermediate point, `|wins - losses| ≥ k`

This can be solved using dynamic programming where the state is the current balance (wins - losses).

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "NO"

    n, k = map(int, lines[0].split())
    s = lines[1]

    if n <= 0:
        return "NO"

    # offset to make balances non-negative indices
    offset = k - 1
    size = 2 * k  # balances range from -(k-1) to (k-1)

    # dp[balance + offset] = True if this balance is reachable
    # choice[position][balance + offset] = character that led to this balance
    dp_prev = [False] * size
    dp_prev[offset] = True  # Starting balance is 0

    choice = [[None] * size for _ in range(n)]

    for i in range(n - 1):
        dp_curr = [False] * size

        for b in range(size):
            if dp_prev[b]:
                actual_balance = b - offset

                if s[i] == '?':
                    candidates = ['W', 'L', 'D']
                elif s[i] == 'W':
                    candidates = ['W']
                elif s[i] == 'L':
                    candidates = ['L']
                else:  # 'D'
                    candidates = ['D']

                for char in candidates:
                    new_balance = actual_balance
                    if char == 'W':
                        new_balance += 1
                    elif char == 'L':
                        new_balance -= 1
                    # D doesn't change balance

                    new_idx = new_balance + offset
                    if 0 <= new_idx < size:
                        # At positions 0 to n-2, we need |balance| < k
                        if abs(new_balance) >= k:
                            continue
