```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "NO"

    n, k = map(int, lines[0].split())
    s = lines[1]

    if n <= 0:
        return "NO"

    offset = k
    size = 2 * k + 1

    dp = [False] * size
    dp[offset] = True

    choice = [[None] * size for _ in range(n)]

    for i in range(n):
        new_dp = [False] * size

        for b in range(size):
            if dp[b]:
                bal = b - offset

                if s[i] == '?':
                    opts = ['W', 'L', 'D']
                elif s[i] == 'W':
                    opts = ['W']
                elif s[i] == 'L':
                    opts = ['L']
                else:
                    opts = ['D']

                for c in opts:
                    nxt = bal + (1 if c == 'W' else -1 if c == 'L' else 0)
                    nx = nxt + offset

                    if nx < 0 or nx >= size:
                        continue

                    if i < n - 1:
                        if abs(nxt) < k:
                            new_dp[nx] = True
                            choice[i][nx] = c
                    else:
                        if abs(nxt) == k:
                            new_dp[nx] = True
                            choice[i][nx] = c

        dp = new_dp

    if not any(dp):
        return "NO"

    result = []
    for i in range(n - 1, -1, -1):
        for b in range(size):
            if dp[b] and choice[i][b] is not None:
                result.append(choice[i][b])
                dp[b] = False
                break

    result.reverse()
    return ''.join(result)
